class Stage15TInstallerError(RuntimeError):
    pass


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def compact_utc() -> str:
    return dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path, chunk: int = 8 * 1024 * 1024) -> str:
    h = hashlib.sha256()
    with path.open("rb") as fh:
        for block in iter(lambda: fh.read(chunk), b""):
            h.update(block)
    return h.hexdigest()


def final_ssot_source_bytes() -> bytes:
    data = zlib.decompress(base64.b64decode("".join(FINAL_SSOT_SOURCE_ZLIB_B64.split())))
    if sha256_bytes(data) != FINAL_SSOT_SOURCE_SHA256:
        raise Stage15TInstallerError("embedded final SSOT source SHA mismatch")
    return data


def promotion_audit_bytes() -> bytes:
    data = zlib.decompress(base64.b64decode("".join(INSTALLER_PROMOTION_AUDIT_ZLIB_B64.split())))
    if sha256_bytes(data) != INSTALLER_PROMOTION_AUDIT_SHA256:
        raise Stage15TInstallerError("embedded installer promotion-audit SHA mismatch")
    return data


def ensure_regular(path: Path, label: str = "file") -> None:
    if not path.is_file() or path.is_symlink():
        raise Stage15TInstallerError(f"required regular {label} missing/invalid: {path}")


def ensure_no_symlink_chain(path: Path, stop: Path) -> None:
    current = path
    stop = stop.resolve()
    while True:
        if current.is_symlink():
            raise Stage15TInstallerError(f"symlink prohibited in guarded path: {current}")
        if current.resolve(strict=False) == stop:
            break
        if current.parent == current:
            raise Stage15TInstallerError(f"path escapes guard root: {path}")
        current = current.parent


def reject_symlinks_under(root: Path) -> None:
    if root.is_symlink():
        raise Stage15TInstallerError(f"symlink root prohibited: {root}")
    if not root.exists():
        return
    for path in root.rglob("*"):
        if path.is_symlink():
            raise Stage15TInstallerError(f"symlink prohibited under guarded tree: {path}")


def read_tsv(path: Path) -> list[dict[str, str]]:
    ensure_regular(path, "TSV")
    with path.open("r", encoding="utf-8", newline="") as fh:
        return list(csv.DictReader(fh, delimiter="\t"))


def tsv_bytes(rows: Iterable[dict[str, Any]], fields: Sequence[str]) -> bytes:
    import io
    out = io.StringIO(newline="")
    writer = csv.DictWriter(
        out, delimiter="\t", fieldnames=list(fields), extrasaction="ignore", lineterminator="\n"
    )
    writer.writeheader()
    writer.writerows(rows)
    return out.getvalue().encode("utf-8")


def fsync_dir(path: Path) -> None:
    fd = os.open(path, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def atomic_write_bytes(destination: Path, data: bytes, mode: int = 0o644) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    temp = destination.with_name(f".{destination.name}.stage15t.{os.getpid()}.part")
    if temp.exists():
        temp.unlink()
    try:
        with temp.open("xb") as fh:
            fh.write(data)
            fh.flush()
            os.fsync(fh.fileno())
        os.chmod(temp, mode)
        os.replace(temp, destination)
        fsync_dir(destination.parent)
    finally:
        temp.unlink(missing_ok=True)


def atomic_copy_file(source: Path, destination: Path) -> None:
    ensure_regular(source, "copy source")
    destination.parent.mkdir(parents=True, exist_ok=True)
    temp = destination.with_name(f".{destination.name}.stage15t.{os.getpid()}.part")
    if temp.exists():
        temp.unlink()
    try:
        with source.open("rb") as src, temp.open("xb") as dst:
            shutil.copyfileobj(src, dst, length=8 * 1024 * 1024)
            dst.flush()
            os.fsync(dst.fileno())
        os.chmod(temp, source.stat().st_mode & 0o777)
        os.replace(temp, destination)
        fsync_dir(destination.parent)
    finally:
        temp.unlink(missing_ok=True)


def copy_tree_exact(source: Path, destination: Path) -> None:
    if not source.is_dir() or source.is_symlink():
        raise Stage15TInstallerError(f"invalid tree source: {source}")
    reject_symlinks_under(source)
    if destination.exists():
        raise Stage15TInstallerError(f"destination already exists: {destination}")
    shutil.copytree(source, destination, symlinks=False)
    reject_symlinks_under(destination)


def remove_path(path: Path) -> None:
    if path.is_symlink():
        path.unlink()
    elif path.is_dir():
        shutil.rmtree(path)
    elif path.exists():
        path.unlink()


def iter_regular_files(root: Path) -> Iterator[Path]:
    if root.is_file() and not root.is_symlink():
        yield root
        return
    if root.is_dir() and not root.is_symlink():
        for path in sorted(root.rglob("*")):
            if path.is_symlink():
                raise Stage15TInstallerError(f"symlink prohibited while inventorying: {path}")
            if path.is_file():
                yield path


def inventory_targets(project_root: Path, targets: Iterable[str]) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    seen: set[str] = set()
    for target_rel in targets:
        target = project_root / target_rel
        if not target.exists():
            continue
        ensure_no_symlink_chain(target, project_root)
        for path in iter_regular_files(target):
            rel = path.relative_to(project_root).as_posix()
            if rel in seen:
                continue
            seen.add(rel)
            rows.append({"path": rel, "bytes": str(path.stat().st_size), "sha256": sha256_file(path)})
    return sorted(rows, key=lambda row: row["path"])


def verify_inventory(project_root: Path, rows: list[dict[str, str]], targets: Iterable[str]) -> None:
    actual = inventory_targets(project_root, targets)
    expected_map = {row["path"]: (str(row["bytes"]), row["sha256"]) for row in rows}
    actual_map = {row["path"]: (str(row["bytes"]), row["sha256"]) for row in actual}
    if actual_map != expected_map:
        missing = sorted(set(expected_map) - set(actual_map))[:20]
        extra = sorted(set(actual_map) - set(expected_map))[:20]
        drift = sorted(k for k in set(actual_map) & set(expected_map) if actual_map[k] != expected_map[k])[:20]
        raise Stage15TInstallerError(f"inventory mismatch: missing={missing}; extra={extra}; drift={drift}")


def verify_manifest_rows(root: Path, rows: list[dict[str, str]], label: str) -> int:
    if not rows:
        raise Stage15TInstallerError(f"{label} is empty")
    seen: set[str] = set()
    for row in rows:
        raw = row.get("path", "")
        rel = Path(raw)
        if not raw or rel.is_absolute() or ".." in rel.parts or raw in seen:
            raise Stage15TInstallerError(f"unsafe/duplicate {label} path: {raw!r}")
        seen.add(raw)
        path = root / rel
        ensure_no_symlink_chain(path, root)
        ensure_regular(path, label)
        if path.stat().st_size != int(row["bytes"]) or sha256_file(path) != row["sha256"]:
            raise Stage15TInstallerError(f"{label} mismatch: {raw}")
    return len(rows)


def verify_historical_manifest(project_root: Path) -> tuple[int, str]:
    manifest = project_root / BASE_FREEZE_MANIFEST_REL
    ensure_regular(manifest, "historical v0.1.0 manifest")
    digest = sha256_file(manifest)
    if digest != EXPECTED_PRESTATE[BASE_FREEZE_MANIFEST_REL.as_posix()]:
        raise Stage15TInstallerError(f"historical manifest SHA drift: {digest}")
    rows = read_tsv(manifest)
    count = verify_manifest_rows(project_root, rows, "historical v0.1.0 manifest")
    if count != BASE_FREEZE_MANIFEST_ROWS:
        raise Stage15TInstallerError(f"historical manifest row count mismatch: {count}")
    return count, digest


def verify_artifact_manifest(root: Path) -> int:
    manifest = root / "artifact_manifest.tsv"
    if sha256_file(manifest) != CORRECTED_PREFLIGHT_MANIFEST_SHA256:
        raise Stage15TInstallerError("corrected-preflight artifact manifest SHA mismatch")
    rows = read_tsv(manifest)
    count = verify_manifest_rows(root, rows, "corrected-preflight artifact manifest")
    recorded = {row["path"] for row in rows}
    actual = {
        path.relative_to(root).as_posix()
        for path in iter_regular_files(root)
        if path.relative_to(root).as_posix() != "artifact_manifest.tsv"
        and "__pycache__" not in path.relative_to(root).parts
        and path.suffix != ".pyc"
    }
    if recorded != actual:
        raise Stage15TInstallerError(
            f"corrected-preflight manifest coverage mismatch: missing={sorted(actual-recorded)}; extra={sorted(recorded-actual)}"
        )
    return count


def parse_sidecar(sidecar: Path, archive: Path, expected_sha: str | None = None) -> str:
    ensure_regular(sidecar, "SHA sidecar")
    ensure_regular(archive, "archive")
    parts = sidecar.read_text(encoding="utf-8").strip().split()
    if len(parts) < 2 or len(parts[0]) != 64 or parts[-1] != archive.name:
        raise Stage15TInstallerError(f"invalid/mismatched sidecar: {sidecar}")
    actual = sha256_file(archive)
    if actual != parts[0]:
        raise Stage15TInstallerError(f"archive SHA mismatch: {archive}: {actual} != {parts[0]}")
    if expected_sha is not None and actual != expected_sha:
        raise Stage15TInstallerError(f"unexpected archive SHA: {actual} != {expected_sha}")
    return actual


def verify_self_sidecar() -> str:
    source = Path(__file__).resolve()
    expected_name = "rnatr_stage15t_final_core_freeze_installer_v013.py"
    if source.name != expected_name:
        raise Stage15TInstallerError(
            f"installer must retain exact filename {expected_name}: observed={source.name}"
        )
    sidecar = source.with_name(source.name + ".sha256")
    return parse_sidecar(sidecar, source)


def resolve_by_sha(downloads: Path, logical_name: str, expected_sha: str) -> Path:
    prefix = logical_name.split(".tar", 1)[0]
    candidates = sorted(
        (
            path for path in downloads.iterdir()
            if path.is_file() and not path.is_symlink() and path.name.startswith(prefix)
        ),
        key=lambda path: path.name,
    )
    matches = [path for path in candidates if sha256_file(path) == expected_sha]
    if not matches:
        raise Stage15TInstallerError(f"input resolution failed: {logical_name}: no SHA-matching file")
    exact = [path for path in matches if path.name == logical_name]
    if exact:
        return exact[0]
    # Browser-created duplicate names are content-equivalent after exact SHA binding.
    return matches[0]


def load_embedded_ssot_module() -> dict[str, Any]:
    source = final_ssot_source_bytes()
    namespace: dict[str, Any] = {
        "__name__": "rnatr_stage15t_final_ssot_embedded",
        "__file__": "<embedded-rnatr-ssot-stage15t>",
    }
    exec(compile(source, namespace["__file__"], "exec"), namespace)
    for name in ("_stage15t_apply_registration_overlay", "export_query"):
        if not callable(namespace.get(name)):
            raise Stage15TInstallerError(f"embedded final SSOT source missing callable: {name}")
    return namespace


def sqlite_table_names(conn: sqlite3.Connection) -> list[str]:
    return [
        row[0] for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        )
    ]


def quote_identifier(name: str) -> str:
    return '"' + name.replace('"', '""') + '"'


def compare_sqlite_logical(actual_db: Path, expected_db: Path) -> int:
    ensure_regular(actual_db, "runtime simulated SSOT DB")
    ensure_regular(expected_db, "preflight simulated SSOT DB")
    conn = sqlite3.connect(actual_db)
    try:
        conn.execute("ATTACH DATABASE ? AS expected", (str(expected_db),))
        main_tables = sqlite_table_names(conn)
        expected_tables = [
            row[0] for row in conn.execute(
                "SELECT name FROM expected.sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
            )
        ]
        if main_tables != expected_tables:
            raise Stage15TInstallerError("runtime/preflight SSOT table-set mismatch")
        for table in main_tables:
            q = quote_identifier(table)
            main_info = conn.execute(f"PRAGMA main.table_info({q})").fetchall()
            exp_info = conn.execute(f"PRAGMA expected.table_info({q})").fetchall()
            if main_info != exp_info:
                raise Stage15TInstallerError(f"runtime/preflight SSOT schema mismatch: {table}")
            count_main = conn.execute(f"SELECT COUNT(*) FROM main.{q}").fetchone()[0]
            count_exp = conn.execute(f"SELECT COUNT(*) FROM expected.{q}").fetchone()[0]
            if count_main != count_exp:
                raise Stage15TInstallerError(f"runtime/preflight SSOT row-count mismatch: {table}")
            columns = [quote_identifier(str(row[1])) for row in main_info]
            if not columns:
                raise Stage15TInstallerError(f"SSOT table has no columns: {table}")
            order_clause = ", ".join(columns)
            main_cursor = conn.execute(f"SELECT * FROM main.{q} ORDER BY {order_clause}")
            exp_cursor = conn.execute(f"SELECT * FROM expected.{q} ORDER BY {order_clause}")
            while True:
                main_batch = main_cursor.fetchmany(1024)
                exp_batch = exp_cursor.fetchmany(1024)
                if main_batch != exp_batch:
                    raise Stage15TInstallerError(f"runtime/preflight SSOT exact-row mismatch: {table}")
                if not main_batch:
                    break
        return len(main_tables)
    finally:
        conn.close()


def runtime_ssot_overlay_audit(project_root: Path, preflight_root: Path) -> dict[str, Any]:
    module = load_embedded_ssot_module()
    live_db = project_root / "metadata/ssot/rnatr_ssot.sqlite"
    expected_db = preflight_root / "ssot_simulation/rnatr_ssot.simulated_poststate.sqlite"
    if sha256_file(expected_db) != PREFLIGHT_SIMULATED_DB_SHA256:
        raise Stage15TInstallerError("preflight simulated SSOT DB drift")
    with tempfile.TemporaryDirectory(prefix="rnatr_stage15t_ssot_runtime_audit_") as td:
        temp_root = Path(td)
        runtime_db = temp_root / "runtime.sqlite"
        shutil.copy2(live_db, runtime_db)
        conn = sqlite3.connect(runtime_db)
        try:
            conn.execute("PRAGMA foreign_keys=ON")
            module["_stage15t_apply_registration_overlay"](conn, str(DEFAULT_PROJECT_ROOT))
            conn.commit()
            integrity = conn.execute("PRAGMA integrity_check").fetchone()[0]
            fk_rows = conn.execute("PRAGMA foreign_key_check").fetchall()
            if integrity != "ok" or fk_rows:
                raise Stage15TInstallerError(f"runtime SSOT overlay integrity failure: {integrity}; fk={fk_rows[:5]}")
            exports = temp_root / "exports"
            exports.mkdir()
            for filename, expected_sha in SIMULATED_VIEW_SHA256.items():
                view = filename.removesuffix(".tsv")
                out = exports / filename
                module["export_query"](conn, f"SELECT * FROM {view}", out)
                expected = preflight_root / "ssot_simulation" / filename
                if sha256_file(expected) != expected_sha:
                    raise Stage15TInstallerError(f"preflight simulated view drift: {filename}")
                if out.read_bytes() != expected.read_bytes():
                    raise Stage15TInstallerError(f"runtime SSOT overlay view mismatch: {filename}")
        finally:
            conn.close()
        table_count = compare_sqlite_logical(runtime_db, expected_db)
        return {
            "integrity": "PASS",
            "foreign_key_check_rows": 0,
            "compared_views": len(SIMULATED_VIEW_SHA256),
            "compared_tables": table_count,
        }


def prepare_ssot_audit_payload_root(preflight_root: Path, destination: Path) -> Path:
    payload_root = preflight_root / "installer_payload"
    for source_rel, destination_rel in sorted(PAYLOAD_INSTALL_MAP.items(), key=lambda item: item[1]):
        source = payload_root / source_rel
        target = destination / destination_rel
        atomic_copy_file(source, target)
    atomic_write_bytes(destination / CURRENT_STRUCTURE_POINTER_REL, CURRENT_STRUCTURE_POINTER_BYTES)
    return destination


def load_ssot_full_rebuild_audit_module(payload_root: Path) -> dict[str, Any]:
    source = final_ssot_source_bytes()
    needle = b"_s15t_path = (project_root / _s15t_rel).resolve()"
    replacement = b"_s15t_path = (Path(STAGE15T_AUDIT_PAYLOAD_ROOT) / _s15t_rel).resolve()"
    if source.count(needle) != 1:
        raise Stage15TInstallerError("unable to construct exact-source full-rebuild audit variant")
    audit_source = source.replace(needle, replacement, 1)
    namespace: dict[str, Any] = {
        "__name__": "rnatr_stage15t_final_ssot_full_rebuild_audit",
        "__file__": "<embedded-rnatr-ssot-stage15t-full-rebuild-audit>",
        "STAGE15T_AUDIT_PAYLOAD_ROOT": str(payload_root),
    }
    exec(compile(audit_source, namespace["__file__"], "exec"), namespace)
    required_callables = (
        "ensure_stage",
        "import_legacy_sqlite",
        "import_legacy_exports",
        "scan_scripts",
        "scan_qc",
        "scan_manifests",
        "scan_checkpoints",
        "seed_curated",
        "validate_db",
        "export_query",
    )
    for name in required_callables:
        if not callable(namespace.get(name)):
            raise Stage15TInstallerError(f"full-rebuild audit module missing callable: {name}")
    for name in ("SCHEMA_SQL", "SCHEMA_VERSION", "TOOL_VERSION", "NOW"):
        if name not in namespace:
            raise Stage15TInstallerError(f"full-rebuild audit module missing global: {name}")
    return namespace


def runtime_full_ssot_rebuild_audit(project_root: Path, preflight_root: Path) -> dict[str, Any]:
    """Rebuild the final SSOT into a temporary DB while reading the live project only.

    The only source transformation is an audit-only redirection of the Stage15T new-file
    SHA guards to an exact temporary copy of the already-verified installer payload. The
    source installed in the project remains the strict, unmodified embedded source.
    """
    ssot_pre = inventory_targets(project_root, BACKUP_TARGETS)
    with tempfile.TemporaryDirectory(prefix="rnatr_stage15t_ssot_full_rebuild_audit_") as td:
        temp_root = Path(td)
        audit_payload_root = prepare_ssot_audit_payload_root(preflight_root, temp_root / "payload")
        module = load_ssot_full_rebuild_audit_module(audit_payload_root)
        db = temp_root / "full_rebuild.sqlite"
        conn = sqlite3.connect(db)
        conn.row_factory = sqlite3.Row
        try:
            conn.executescript(module["SCHEMA_SQL"])
            started = module["NOW"]()
            conn.execute("INSERT INTO schema_info(key,value) VALUES('schema_version',?)", (str(module["SCHEMA_VERSION"]),))
            conn.execute("INSERT INTO schema_info(key,value) VALUES('tool_version',?)", (module["TOOL_VERSION"],))
            conn.execute("INSERT INTO schema_info(key,value) VALUES('project_root',?)", (str(project_root),))
            conn.execute("INSERT INTO schema_info(key,value) VALUES('generated_at',?)", (started,))
            ingestion_id = conn.execute(
                """
                INSERT INTO ingestion_runs(started_at,status,tool_version,project_root,notes)
                VALUES(?,?,?,?,?)
                """,
                (
                    started,
                    "RUNNING",
                    module["TOOL_VERSION"],
                    str(project_root),
                    "Stage15T read-only full SSOT rebuild audit into a temporary database.",
                ),
            ).lastrowid
            module["ensure_stage"](
                conn,
                "SSOT_INGEST",
                order=0,
                name="SSOT ingestion",
                purpose="Build the single source of truth database.",
                category="infrastructure",
                status="IMPLEMENTED",
            )
            old_db = project_root / "metadata/build_tracker/rnatr_build_tracker.sqlite"
            old_sha = module["import_legacy_sqlite"](conn, old_db)
            module["import_legacy_exports"](conn, project_root / "metadata/build_tracker")
            module["scan_scripts"](conn, project_root)
            module["scan_qc"](conn, project_root)
            module["scan_manifests"](conn, project_root)
            module["scan_checkpoints"](conn, project_root)
            module["seed_curated"](conn, project_root)
            checks = module["validate_db"](conn, project_root)
            failed = [row for row in checks if row[1] == "FAIL"]
            conn.execute(
                "UPDATE ingestion_runs SET finished_at=?,status=?,old_tracker_db_sha256=? WHERE ingestion_id=?",
                (module["NOW"](), "FAIL" if failed else "PASS", old_sha, ingestion_id),
            )
            conn.commit()
            if failed:
                report = "; ".join(f"{name}:{detail}" for name, _, detail in failed)
                raise Stage15TInstallerError(f"read-only full SSOT rebuild validation failed: {report}")
            integrity = conn.execute("PRAGMA integrity_check").fetchone()[0]
            fk_rows = conn.execute("PRAGMA foreign_key_check").fetchall()
            if integrity != "ok" or fk_rows:
                raise Stage15TInstallerError(
                    f"read-only full SSOT rebuild integrity failure: {integrity}; fk={fk_rows[:5]}"
                )
            exports = temp_root / "exports"
            exports.mkdir()
            for filename, expected_sha in SIMULATED_VIEW_SHA256.items():
                view = filename.removesuffix(".tsv")
                out = exports / filename
                module["export_query"](conn, f"SELECT * FROM {view}", out)
                expected = preflight_root / "ssot_simulation" / filename
                if sha256_file(expected) != expected_sha:
                    raise Stage15TInstallerError(f"preflight simulated view drift: {filename}")
                if out.read_bytes() != expected.read_bytes():
                    raise Stage15TInstallerError(f"read-only full SSOT rebuild view mismatch: {filename}")
            warning_count = conn.execute("SELECT COUNT(*) FROM scan_warnings").fetchone()[0]
        finally:
            conn.close()
    verify_inventory(project_root, ssot_pre, BACKUP_TARGETS)
    return {
        "integrity": "PASS",
        "foreign_key_check_rows": 0,
        "validation_checks": len(checks),
        "validation_failures": 0,
        "compared_views": len(SIMULATED_VIEW_SHA256),
        "scan_warnings": warning_count,
        "project_ssot_immutability": "PASS",
    }


def run_command(command: list[str], log: Path, env: dict[str, str] | None = None) -> None:
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("w", encoding="utf-8") as fh:
        proc = subprocess.run(command, stdout=fh, stderr=subprocess.STDOUT, text=True, env=env)
        fh.flush()
        os.fsync(fh.fileno())
    if proc.returncode != 0:
        tail = "\n".join(log.read_text(encoding="utf-8", errors="replace").splitlines()[-50:])
        raise Stage15TInstallerError(f"command failed ({proc.returncode}): {' '.join(command)}\n{tail}")


def verify_execution_prestate_after_lock(preflight_root: Path, project_root: Path) -> None:
    prestate_rows = read_tsv(preflight_root / "prestate_guards.tsv")
    project_rows = [row for row in prestate_rows if row.get("kind") == "project_file"]
    if len(project_rows) != 20:
        raise Stage15TInstallerError(f"unexpected post-lock project prestate guard count: {len(project_rows)}")
    for row in project_rows:
        path = project_root / row["path"]
        ensure_no_symlink_chain(path, project_root)
        ensure_regular(path, "post-lock live prestate file")
        if path.stat().st_size != int(row["bytes"]) or sha256_file(path) != row["expected_sha256"]:
            raise Stage15TInstallerError(f"post-lock live project prestate drift: {row['path']}")
    for rel, expected in EXPECTED_PRESTATE.items():
        path = project_root / rel
        ensure_regular(path, "post-lock critical live prestate file")
        if sha256_file(path) != expected:
            raise Stage15TInstallerError(f"post-lock critical live prestate drift: {rel}")
    verify_historical_manifest(project_root)
    for rel in NEW_PATHS_MUST_BE_ABSENT:
        if (project_root / rel).exists():
            raise Stage15TInstallerError(f"post-lock registration path unexpectedly exists: {rel}")
    if (project_root / ROLLBACK_REL).exists():
        raise Stage15TInstallerError(f"post-lock rollback root unexpectedly exists: {project_root / ROLLBACK_REL}")


def verify_corrected_preflight(root: Path, downloads: Path, project_root: Path) -> dict[str, Any]:
    if not root.is_dir() or root.is_symlink():
        raise Stage15TInstallerError(f"corrected preflight root missing/invalid: {root}")
    reject_symlinks_under(root)
    manifest_count = verify_artifact_manifest(root)

    qc = {row["metric"]: row["value"] for row in read_tsv(root / "stage15t_corrected_preflight.qc.tsv")}
    for key, expected in REQUIRED_QC.items():
        if qc.get(key) != expected:
            raise Stage15TInstallerError(f"corrected-preflight QC mismatch: {key}: {qc.get(key)} != {expected}")

    for rel, expected in CRITICAL_PREFLIGHT_FILES.items():
        path = root / rel
        ensure_regular(path, "critical corrected-preflight file")
        if sha256_file(path) != expected:
            raise Stage15TInstallerError(f"critical corrected-preflight file drift: {rel}")

    payload_root = root / "installer_payload"
    actual_payload = {path.relative_to(payload_root).as_posix(): sha256_file(path) for path in iter_regular_files(payload_root)}
    missing = sorted(set(PAYLOAD_SOURCE_HASHES) - set(actual_payload))
    drift = sorted(k for k in PAYLOAD_SOURCE_HASHES if k in actual_payload and actual_payload[k] != PAYLOAD_SOURCE_HASHES[k])
    extras = set(actual_payload) - set(PAYLOAD_SOURCE_HASHES)
    unsupported_extras = sorted(extras - set(PAYLOAD_NONINSTALL_EXTRA_HASHES))
    extra_drift = sorted(k for k in extras & set(PAYLOAD_NONINSTALL_EXTRA_HASHES) if actual_payload[k] != PAYLOAD_NONINSTALL_EXTRA_HASHES[k])
    if missing or drift or unsupported_extras or extra_drift:
        raise Stage15TInstallerError(
            f"installer payload mismatch: missing={missing}; drift={drift}; "
            f"unsupported_extras={unsupported_extras}; extra_drift={extra_drift}"
        )

    packet_src = (root / "approved_sources/RNA_TR_Scout_Core_Freeze_Packet_v0.1.1_OWNER_APPROVED_SOURCE.md").read_bytes()
    packet_canonical = (payload_root / "docs/core_freeze/v0.1.1/RNA_TR_Scout_Core_Freeze_Packet_v0.1.1.md").read_bytes()
    if packet_canonical.count(packet_src) != 1:
        raise Stage15TInstallerError("canonical Packet does not contain exact owner-approved source once")
    ctc_src = (root / "approved_sources/RNA_TR_Scout_Core_Technical_Completion_and_Freeze_contract_v0.1.2_OWNER_APPROVED_SOURCE.md").read_bytes()
    ctc_canonical = (payload_root / "docs/contracts/RNA_TR_Scout_Core_Technical_Completion_and_Freeze_contract_v0.1.2.md").read_bytes()
    if ctc_canonical.count(ctc_src) != 1:
        raise Stage15TInstallerError("canonical CTC contract does not contain exact owner-approved source once")
    if (root / "approved_sources/release_gates_v0.3.4.owner_approved.tsv").read_bytes() != (
        payload_root / "validation/release_gates_v0.3.4.tsv"
    ).read_bytes():
        raise Stage15TInstallerError("release-gate payload is not exact owner-approved bytes")

    immutability_rows = read_tsv(root / "project_source_immutability.tsv")
    if not immutability_rows or any(row.get("status") != "PASS" for row in immutability_rows):
        raise Stage15TInstallerError("corrected-preflight project immutability evidence is not all PASS")

    prestate_rows = read_tsv(root / "prestate_guards.tsv")
    project_rows = [row for row in prestate_rows if row.get("kind") == "project_file"]
    if len(project_rows) != 20:
        raise Stage15TInstallerError(f"unexpected project prestate guard count: {len(project_rows)}")
    for row in project_rows:
        path = project_root / row["path"]
        ensure_no_symlink_chain(path, project_root)
        ensure_regular(path, "live prestate file")
        if path.stat().st_size != int(row["bytes"]) or sha256_file(path) != row["expected_sha256"]:
            raise Stage15TInstallerError(f"live project prestate drift: {row['path']}")
    for rel, expected in EXPECTED_PRESTATE.items():
        path = project_root / rel
        ensure_regular(path, "critical live prestate file")
        if sha256_file(path) != expected:
            raise Stage15TInstallerError(f"critical live prestate drift: {rel}")

    historical_rows, historical_sha = verify_historical_manifest(project_root)

    for rel in NEW_PATHS_MUST_BE_ABSENT:
        if (project_root / rel).exists():
            raise Stage15TInstallerError(f"new registration path already exists: {rel}")
    if (project_root / ROLLBACK_REL).exists():
        raise Stage15TInstallerError(f"active rollback root already exists: {project_root / ROLLBACK_REL}")
    if (project_root / LOCK_REL).exists():
        raise Stage15TInstallerError(f"registration lock already exists: {project_root / LOCK_REL}")

    input_paths: dict[str, Path] = {}
    for row in read_tsv(root / "input_bundle_binding.tsv"):
        logical = row["logical_name"]
        logical_path = Path(logical)
        if row.get("status") != "PASS" or logical_path.is_absolute() or ".." in logical_path.parts or logical_path.name != logical:
            raise Stage15TInstallerError(f"unsafe/non-PASS input bundle binding: {row}")
        if logical in input_paths:
            raise Stage15TInstallerError(f"duplicate input bundle logical name: {logical}")
        input_paths[logical] = resolve_by_sha(downloads, logical, row["sha256"])

    corrected_archive = downloads / f"{CORRECTED_PREFLIGHT_NAME}.tar.gz"
    corrected_sidecar = downloads / f"{CORRECTED_PREFLIGHT_NAME}.tar.gz.sha256"
    corrected_sha = parse_sidecar(corrected_sidecar, corrected_archive, CORRECTED_PREFLIGHT_ARCHIVE_SHA256)
    corrected_run_log = resolve_by_sha(
        downloads,
        "rnatr_stage15t_corrected_installer_preflight_v013.run.log",
        CORRECTED_PREFLIGHT_RUN_LOG_SHA256,
    )

    final_source = final_ssot_source_bytes()
    compile(final_source, "<embedded-final-stage15t-ssot>", "exec")
    if b"docs/README_CANONICAL_STRUCTURE_v0.1.1.md" not in final_source or b"docs/CURRENT_CANONICAL_STRUCTURE.tsv" not in final_source:
        raise Stage15TInstallerError("final SSOT source lacks versioned README/pointer guards")
    if b"STAGE15T_EFFECTIVE_AT" not in final_source:
        raise Stage15TInstallerError("final SSOT source lacks defined Stage15T effective-at constant")

    overlay = runtime_ssot_overlay_audit(project_root, root)
    full_rebuild = runtime_full_ssot_rebuild_audit(project_root, root)

    with tempfile.TemporaryDirectory(prefix="rnatr_stage15t_golden_selftest_") as td:
        golden = payload_root / "validation/golden/v0.1.1/rnatr_golden_regression_v015.py"
        compile(golden.read_text(encoding="utf-8"), str(golden), "exec")
        log = Path(td) / "golden_selftest.log"
        run_command([sys.executable, str(golden), "--self-test"], log, {**os.environ, "PYTHONHASHSEED": "0"})
        if "SELF_TEST_PASS" not in log.read_text(encoding="utf-8"):
            raise Stage15TInstallerError("golden v0.1.5 self-test did not report PASS")

    if sha256_bytes(CURRENT_STRUCTURE_POINTER_BYTES) != CURRENT_STRUCTURE_POINTER_SHA256:
        raise Stage15TInstallerError("embedded canonical-structure pointer SHA mismatch")
    promotion_audit_bytes()

    return {
        "manifest_count": manifest_count,
        "project_guard_count": len(project_rows),
        "historical_manifest_rows": historical_rows,
        "historical_manifest_sha256": historical_sha,
        "input_paths": input_paths,
        "corrected_archive": corrected_archive,
        "corrected_sidecar": corrected_sidecar,
        "corrected_archive_sha256": corrected_sha,
        "corrected_run_log": corrected_run_log,
        "ssot_overlay": overlay,
        "ssot_full_rebuild": full_rebuild,
    }


def build_manifest(project_root: Path, extra_paths: Iterable[Path]) -> list[dict[str, str]]:
    base_rows = read_tsv(project_root / BASE_FREEZE_MANIFEST_REL)
    rels: set[str] = {row["path"] for row in base_rows}
    for path in extra_paths:
        if path.is_dir() and not path.is_symlink():
            for child in iter_regular_files(path):
                rels.add(child.relative_to(project_root).as_posix())
        elif path.is_file() and not path.is_symlink():
            rels.add(path.relative_to(project_root).as_posix())
        elif path.exists():
            raise Stage15TInstallerError(f"manifest extra path invalid: {path}")
    rels.discard((FREEZE_ROOT_REL / "core_freeze_manifest.tsv").as_posix())
    rels.discard((FREEZE_ROOT_REL / "core_freeze_manifest.tsv.sha256").as_posix())
    rows: list[dict[str, str]] = []
    for rel in sorted(rels):
        path = project_root / rel
        ensure_no_symlink_chain(path, project_root)
        ensure_regular(path, "manifest source")
        rows.append({"path": rel, "bytes": str(path.stat().st_size), "sha256": sha256_file(path)})
    return rows


def verify_project_manifest(project_root: Path, manifest: Path) -> int:
    return verify_manifest_rows(project_root, read_tsv(manifest), "final v0.1.1 manifest")


def write_project_manifest(project_root: Path, extra_paths: Iterable[Path]) -> tuple[int, str]:
    manifest = project_root / FREEZE_ROOT_REL / "core_freeze_manifest.tsv"
    sidecar = project_root / FREEZE_ROOT_REL / "core_freeze_manifest.tsv.sha256"
    rows = build_manifest(project_root, extra_paths)
    atomic_write_bytes(manifest, tsv_bytes(rows, ["path", "bytes", "sha256"]))
    digest = sha256_file(manifest)
    atomic_write_bytes(sidecar, f"{digest}  {manifest.name}\n".encode())
    count = verify_project_manifest(project_root, manifest)
    if count != len(rows) or sha256_file(manifest) != digest:
        raise Stage15TInstallerError("final manifest verification instability")
    return count, digest


def query_ssot_poststate(db: Path) -> dict[str, Any]:
    conn = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    try:
        integrity = conn.execute("PRAGMA integrity_check").fetchone()[0]
        fk_rows = conn.execute("PRAGMA foreign_key_check").fetchall()
        if integrity != "ok" or fk_rows:
            raise Stage15TInstallerError(f"SSOT integrity/FK failure: {integrity}; {fk_rows[:5]}")
        for key in (
            "ARCHITECTURE_CONSISTENCY_AUDIT_CLOSURE",
            "CORE_FREEZE_PACKET",
            "GOLDEN_REGRESSION_SUITE",
            "PROJECT_WIDE_DOCS_CANONICALIZATION",
        ):
            row = conn.execute("SELECT status,blocking FROM open_questions WHERE question_key=?", (key,)).fetchone()
            if row != ("CLOSED", 0):
                raise Stage15TInstallerError(f"SSOT closure mismatch: {key}: {row}")
        for key in (
            "BIOLOGY_READY_INTERPRETATION_OUTPUT_AUDIT",
            "CLEAN_INSTALL_INTERNAL_BETA",
            "G31_BIOLOGICAL_CANDIDATE_ENTRY_INTERPRETATION",
            "CORE_FREEZE_GIT_TAG_AND_PUBLIC_RELEASE_BINDING",
        ):
            row = conn.execute("SELECT status FROM open_questions WHERE question_key=?", (key,)).fetchone()
            if row != ("OPEN",):
                raise Stage15TInstallerError(f"SSOT open-scope mismatch: {key}: {row}")
        return {
            "integrity": integrity,
            "foreign_key_check_rows": len(fk_rows),
            "active_pipeline_rows": conn.execute("SELECT COUNT(*) FROM current_pipeline").fetchone()[0],
            "active_decisions": conn.execute("SELECT COUNT(*) FROM current_decisions").fetchone()[0],
            "active_contracts": conn.execute("SELECT COUNT(*) FROM current_algorithm_contract").fetchone()[0],
            "open_questions": conn.execute("SELECT COUNT(*) FROM current_open_questions").fetchone()[0],
        }
    finally:
        conn.close()


def verify_unchanged_scientific_prestate(project_root: Path) -> None:
    intended_changes = {"metadata/ssot/rnatr_ssot.py", "metadata/ssot/rnatr_ssot.sqlite"}
    for rel, expected in EXPECTED_PRESTATE.items():
        if rel in intended_changes:
            continue
        path = project_root / rel
        ensure_regular(path, "unchanged prestate file")
        if sha256_file(path) != expected:
            raise Stage15TInstallerError(f"unintended post-install drift: {rel}")
    pipeline = project_root / "metadata/ssot/exports/current_pipeline.tsv"
    if sha256_file(pipeline) != EXPECTED_PRESTATE["metadata/ssot/exports/current_pipeline.tsv"]:
        raise Stage15TInstallerError("active current_pipeline export changed")
    verify_historical_manifest(project_root)


def snapshot_path(source: Path, destination: Path) -> None:
    if source.is_dir() and not source.is_symlink():
        copy_tree_exact(source, destination)
    elif source.is_file() and not source.is_symlink():
        atomic_copy_file(source, destination)
    else:
        raise Stage15TInstallerError(f"snapshot source missing/invalid: {source}")


def create_snapshot(project_root: Path) -> Path:
    snapshot = project_root / FREEZE_ROOT_REL / "snapshot"
    if snapshot.exists():
        raise Stage15TInstallerError("v0.1.1 snapshot already exists")
    snapshot.mkdir(parents=True)
    rels = [
        VERSIONED_README_REL.as_posix(),
        CURRENT_STRUCTURE_POINTER_REL.as_posix(),
        "docs/core_freeze/v0.1.1/RNA_TR_Scout_Core_Freeze_Packet_v0.1.1.md",
        "docs/core_freeze/v0.1.1/approved_sources",
        "docs/contracts/CURRENT_CONTRACTS_v0.1.0.tsv",
        "docs/contracts/RNA_TR_Scout_Core_Technical_Completion_and_Freeze_contract_v0.1.2.md",
        "docs/contracts/approved_sources",
        "docs/contracts/RNA_TR_Scout_Candidate_assignment_reverse_traceability_contract_v0.1.1.md",
        "docs/contracts/RNA_TR_Scout_Future_extensibility_boundary_contract_v0.1.1.md",
        "docs/governance/RNA_TR_Scout_Core_Freeze_final_hygiene_audit_v0.1.0.md",
        "validation/release_gates_v0.3.4.tsv",
        "validation/golden/v0.1.1",
        "metadata/ssot/rnatr_ssot.py",
        "metadata/ssot/rnatr_ssot.sqlite",
        "metadata/ssot/exports",
        "metadata/ssot/CURRENT_STATE.md",
    ]
    for rel in rels:
        snapshot_path(project_root / rel, snapshot / rel)
    scope = {
        "contract_version": "rnatr_core_freeze_delta_snapshot_v0.1.1",
        "freeze_id": FREEZE_ID,
        "snapshot_role": "Stage15T final-governance delta over immutable Stage15Q v0.1.0 base snapshot",
        "base_manifest_path": BASE_FREEZE_MANIFEST_REL.as_posix(),
        "base_manifest_sha256": EXPECTED_PRESTATE[BASE_FREEZE_MANIFEST_REL.as_posix()],
        "historical_readme_preserved_sha256": EXPECTED_PRESTATE["docs/README_CANONICAL_STRUCTURE.md"],
        "current_readme_path": VERSIONED_README_REL.as_posix(),
        "scientific_core_changed": False,
        "schema_changed": False,
        "active_pipeline_changed": False,
    }
    atomic_write_bytes(snapshot / "SNAPSHOT_SCOPE.json", (json.dumps(scope, indent=2, sort_keys=True) + "\n").encode())
    rows = []
    for path in iter_regular_files(snapshot):
        rel = path.relative_to(snapshot).as_posix()
        if rel != "snapshot_inventory.tsv":
            rows.append({"path": rel, "bytes": str(path.stat().st_size), "sha256": sha256_file(path)})
    atomic_write_bytes(snapshot / "snapshot_inventory.tsv", tsv_bytes(rows, ["path", "bytes", "sha256"]))
    return snapshot


class RollbackManager:
    def __init__(self, project_root: Path):
        self.project_root = project_root
        self.root = project_root / ROLLBACK_REL
        self.files_root = self.root / "prestate"
        self.journal = self.root / "journal.json"
        self.records: list[dict[str, Any]] = []
        self.prestate_inventory: list[dict[str, str]] = []
        self.mutated = False

    def initialize(self) -> None:
        if self.root.exists():
            raise Stage15TInstallerError(f"rollback root already exists: {self.root}")
        self.files_root.mkdir(parents=True)
        self.prestate_inventory = inventory_targets(self.project_root, BACKUP_TARGETS)
        for rel in BACKUP_TARGETS:
            source = self.project_root / rel
            record: dict[str, Any] = {"path": rel, "existed": source.exists(), "kind": "absent", "sha256": ""}
            if source.is_file() and not source.is_symlink():
                destination = self.files_root / rel
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, destination)
                if sha256_file(destination) != sha256_file(source):
                    raise Stage15TInstallerError(f"rollback file backup mismatch: {rel}")
                record["kind"] = "file"
                record["sha256"] = sha256_file(source)
            elif source.is_dir() and not source.is_symlink():
                copy_tree_exact(source, self.files_root / rel)
                record["kind"] = "directory"
            elif source.exists():
                raise Stage15TInstallerError(f"rollback target invalid: {source}")
            self.records.append(record)
        atomic_write_bytes(self.root / "prestate_backup_manifest.tsv", tsv_bytes(self.records, ["path", "existed", "kind", "sha256"]))
        atomic_write_bytes(self.root / "prestate_content_manifest.tsv", tsv_bytes(self.prestate_inventory, ["path", "bytes", "sha256"]))
        self.update("BACKUP_COMPLETE")

    def update(self, phase: str, **extra: Any) -> None:
        data = {
            "version": VERSION,
            "freeze_id": FREEZE_ID,
            "phase": phase,
            "mutated": self.mutated,
            "updated_utc": utc_now(),
            **extra,
        }
        atomic_write_bytes(self.journal, (json.dumps(data, indent=2, sort_keys=True) + "\n").encode())

    def mark_mutated(self, phase: str) -> None:
        self.mutated = True
        self.update(phase)

    def capture_failure(self, exc: BaseException) -> None:
        failure = {
            "version": VERSION,
            "freeze_id": FREEZE_ID,
            "captured_utc": utc_now(),
            "exception_type": type(exc).__name__,
            "exception": str(exc),
            "traceback": traceback.format_exc(),
        }
        atomic_write_bytes(self.root / "failure.json", (json.dumps(failure, indent=2, sort_keys=True) + "\n").encode())
        evidence = self.root / "failure_evidence"
        evidence.mkdir(exist_ok=True)
        for rel in (REGISTRATION_QC_ROOT_REL, FREEZE_ROOT_REL / "registration_logs"):
            source = self.project_root / rel
            if source.is_dir() and not source.is_symlink():
                destination = evidence / rel
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copytree(source, destination, symlinks=False, dirs_exist_ok=True)

    def restore(self) -> None:
        if not self.root.is_dir():
            raise Stage15TInstallerError("rollback root missing")
        for rel in NEW_PROJECT_TARGETS:
            remove_path(self.project_root / rel)
        for record in self.records:
            rel = str(record["path"])
            target = self.project_root / rel
            remove_path(target)
            existed = record["existed"] in (True, "True", "true", "1")
            if existed:
                source = self.files_root / rel
                if record["kind"] == "directory":
                    copy_tree_exact(source, target)
                elif record["kind"] == "file":
                    target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(source, target)
                else:
                    raise Stage15TInstallerError(f"invalid rollback record kind: {record}")
        verify_inventory(self.project_root, self.prestate_inventory, BACKUP_TARGETS)
        for rel, expected in EXPECTED_PRESTATE.items():
            path = self.project_root / rel
            ensure_regular(path, "restored prestate file")
            if sha256_file(path) != expected:
                raise Stage15TInstallerError(f"rollback verification failed: {rel}")
        verify_historical_manifest(self.project_root)
        self.update("ROLLBACK_COMPLETE", rollback_status="PASS")

    def write_poststate_guard(self) -> None:
        rows = inventory_targets(self.project_root, POSTSTATE_GUARD_TARGETS)
        atomic_write_bytes(self.root / "poststate_guard.tsv", tsv_bytes(rows, ["path", "bytes", "sha256"]))
        self.update("POSTSTATE_GUARD_WRITTEN", poststate_guard_rows=len(rows))

    def verify_poststate_guard(self) -> None:
        verify_inventory(self.project_root, read_tsv(self.root / "poststate_guard.tsv"), POSTSTATE_GUARD_TARGETS)

    def archive(self, label: str) -> Path:
        self.update(f"ARCHIVING_{label.upper()}")
        destination = self.root.with_name(f"{self.root.name}.{label}.{compact_utc()}")
        if destination.exists():
            raise Stage15TInstallerError(f"rollback archive destination exists: {destination}")
        os.replace(self.root, destination)
        fsync_dir(destination.parent)
        return destination


def acquire_lock(project_root: Path) -> Path:
    lock = project_root / LOCK_REL
    lock.parent.mkdir(parents=True, exist_ok=True)
    try:
        fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    except FileExistsError as exc:
        raise Stage15TInstallerError(f"registration lock exists: {lock}") from exc
    with os.fdopen(fd, "w") as fh:
        fh.write(json.dumps({"pid": os.getpid(), "version": VERSION, "created_utc": utc_now()}) + "\n")
        fh.flush()
        os.fsync(fh.fileno())
    return lock


def install_payload(preflight_root: Path, project_root: Path, rollback: RollbackManager) -> list[dict[str, str]]:
    payload_root = preflight_root / "installer_payload"
    rows: list[dict[str, str]] = []
    rollback.mark_mutated("PAYLOAD_INSTALL_START")
    for source_rel, destination_rel in sorted(PAYLOAD_INSTALL_MAP.items(), key=lambda item: item[1]):
        source = payload_root / source_rel
        destination = project_root / destination_rel
        if destination.exists():
            raise Stage15TInstallerError(f"payload destination unexpectedly exists: {destination_rel}")
        atomic_copy_file(source, destination)
        expected = PAYLOAD_SOURCE_HASHES[source_rel]
        actual = sha256_file(destination)
        if actual != expected:
            raise Stage15TInstallerError(f"installed payload SHA mismatch: {destination_rel}: {actual} != {expected}")
        rows.append({"source": source_rel, "destination": destination_rel, "sha256": actual})
    pointer = project_root / CURRENT_STRUCTURE_POINTER_REL
    if pointer.exists():
        raise Stage15TInstallerError(f"pointer destination unexpectedly exists: {CURRENT_STRUCTURE_POINTER_REL}")
    atomic_write_bytes(pointer, CURRENT_STRUCTURE_POINTER_BYTES)
    if sha256_file(pointer) != CURRENT_STRUCTURE_POINTER_SHA256:
        raise Stage15TInstallerError("installed canonical-structure pointer SHA mismatch")
    rows.append({"source": "EMBEDDED_POINTER", "destination": CURRENT_STRUCTURE_POINTER_REL.as_posix(), "sha256": CURRENT_STRUCTURE_POINTER_SHA256})
    rollback.update("PAYLOAD_INSTALLED", installed_files=len(rows))
    return rows


def copy_evidence_archive(source: Path, evidence_root: Path, logical_name: str) -> dict[str, str]:
    logical_path = Path(logical_name)
    if logical_path.is_absolute() or ".." in logical_path.parts or logical_path.name != logical_name:
        raise Stage15TInstallerError(f"unsafe evidence logical name: {logical_name!r}")
    destination = evidence_root / logical_name
    atomic_copy_file(source, destination)
    digest = sha256_file(destination)
    atomic_write_bytes(evidence_root / f"{logical_name}.sha256", f"{digest}  {logical_name}\n".encode())
    return {"path": destination.relative_to(evidence_root.parent.parent).as_posix(), "sha256": digest, "bytes": str(destination.stat().st_size)}


def copy_registration_evidence(
    preflight_root: Path,
    bindings: dict[str, Any],
    project_root: Path,
) -> list[dict[str, str]]:
    evidence_root = project_root / FREEZE_ROOT_REL / "evidence"
    bundles_root = evidence_root / "input_bundles"
    bundles_root.mkdir(parents=True, exist_ok=True)
    rows: list[dict[str, str]] = []
    for logical, source in sorted(bindings["input_paths"].items()):
        rows.append(copy_evidence_archive(source, bundles_root, logical))
    rows.append(copy_evidence_archive(bindings["corrected_archive"], bundles_root, bindings["corrected_archive"].name))
    atomic_copy_file(bindings["corrected_sidecar"], bundles_root / bindings["corrected_sidecar"].name)
    atomic_copy_file(bindings["corrected_run_log"], bundles_root / "rnatr_stage15t_corrected_installer_preflight_v013.run.log")

    selected = [
        "approved_sources/owner_approval_record.json",
        "audit/RNA_TR_Scout_Stage15T_final_installer_Pro_audit_v0.1.0.md",
        "owner_approved_vs_rejected_payload.tsv",
        "corrected_install_plan.tsv",
        "stage15t_corrected_preflight.qc.tsv",
        "owner_approved_ssot_registration_actions.tsv",
        "owner_approved_final_registration_plan.tsv",
    ]
    for rel in selected:
        source = preflight_root / rel
        destination = evidence_root / "corrected_preflight" / rel
        atomic_copy_file(source, destination)

    pro_audit = evidence_root / "audits/RNA_TR_Scout_Stage15T_final_installer_hotfix_Pro_promotion_audit_v0.1.5.md"
    atomic_write_bytes(pro_audit, promotion_audit_bytes())

    installer_source = Path(__file__).resolve()
    installer_sha = sha256_file(installer_source)
    atomic_copy_file(installer_source, evidence_root / installer_source.name)
    atomic_write_bytes(evidence_root / f"{installer_source.name}.sha256", f"{installer_sha}  {installer_source.name}\n".encode())
    installer_sidecar = installer_source.with_name(installer_source.name + ".sha256")
    parse_sidecar(installer_sidecar, installer_source)
    atomic_copy_file(installer_sidecar, evidence_root / installer_sidecar.name)
    atomic_write_bytes(evidence_root / "input_bundle_binding.tsv", tsv_bytes(rows, ["path", "bytes", "sha256"]))
    return rows


def run_external_final_tier0(project_root: Path, golden: Path, env: dict[str, str]) -> tuple[dict[str, str], bytes, bytes]:
    with tempfile.TemporaryDirectory(prefix="rnatr_stage15t_final_tier0_") as td:
        root = Path(td)
        qc = root / "qc"
        log = root / "run.log"
        run_command(
            [sys.executable, str(golden), "--tier0-only", "--project-root", str(project_root), "--qc-root", str(qc)],
            log,
            env,
        )
        summary_path = qc / "golden_suite_summary.tsv"
        summary = {row["metric"]: row["value"] for row in read_tsv(summary_path)}
        if summary.get("status") != "PASS" or summary.get("tier0") != "PASS":
            raise Stage15TInstallerError(f"external final Tier0 did not pass: {summary}")
        return summary, summary_path.read_bytes(), log.read_bytes()


def create_deterministic_tar_gz(source_root: Path, archive: Path, arc_parent: Path) -> None:
    temp = archive.with_name(f".{archive.name}.stage15t.{os.getpid()}.part")
    temp.unlink(missing_ok=True)
    try:
        with temp.open("wb") as raw:
            with gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0) as gz:
                with tarfile.open(fileobj=gz, mode="w", format=tarfile.PAX_FORMAT) as tf:
                    for path in [source_root] + sorted(source_root.rglob("*")):
                        if path.is_symlink():
                            raise Stage15TInstallerError(f"symlink prohibited in output bundle: {path}")
                        arc = path.relative_to(arc_parent).as_posix()
                        info = tf.gettarinfo(str(path), arcname=arc)
                        info.uid = info.gid = 0
                        info.uname = info.gname = ""
                        info.mtime = 0
                        if path.is_file():
                            with path.open("rb") as fh:
                                tf.addfile(info, fh)
                        else:
                            tf.addfile(info)
            raw.flush()
            os.fsync(raw.fileno())
        os.replace(temp, archive)
        fsync_dir(archive.parent)
    finally:
        temp.unlink(missing_ok=True)


def cleanup_partial_outputs(output_root: Path, output_bundle: Path, output_sidecar: Path) -> None:
    for path in (output_root, output_bundle, output_sidecar):
        remove_path(path)


def execute_install(project_root: Path, downloads: Path, preflight_root: Path, allow_nonstandard_root: bool) -> int:
    bindings = verify_corrected_preflight(preflight_root, downloads, project_root)
    if project_root != DEFAULT_PROJECT_ROOT and not allow_nonstandard_root:
        raise Stage15TInstallerError(f"nonstandard project root prohibited: {project_root}")

    output_root = downloads / OUTPUT_NAME
    output_bundle = downloads / f"{OUTPUT_NAME}.tar.gz"
    output_sidecar = downloads / f"{OUTPUT_NAME}.tar.gz.sha256"
    if output_root.exists() or output_bundle.exists() or output_sidecar.exists():
        raise Stage15TInstallerError("final registration output already exists")

    lock = acquire_lock(project_root)
    rollback = RollbackManager(project_root)
    try:
        verify_execution_prestate_after_lock(preflight_root, project_root)
        rollback.initialize()
        env = {**os.environ, "PYTHONHASHSEED": "0"}

        install_rows = install_payload(preflight_root, project_root, rollback)
        evidence_rows = copy_registration_evidence(preflight_root, bindings, project_root)
        rollback.update("EVIDENCE_INSTALLED", evidence_archives=len(evidence_rows))

        ssot_source_path = project_root / "metadata/ssot/rnatr_ssot.py"
        atomic_write_bytes(ssot_source_path, final_ssot_source_bytes(), mode=0o755)
        if sha256_file(ssot_source_path) != FINAL_SSOT_SOURCE_SHA256:
            raise Stage15TInstallerError("final SSOT source drift after install")
        compile(ssot_source_path.read_text(encoding="utf-8"), str(ssot_source_path), "exec")
        rollback.update("SSOT_SOURCE_INSTALLED", ssot_source_sha256=FINAL_SSOT_SOURCE_SHA256)

        qc_root = project_root / REGISTRATION_QC_ROOT_REL
        logs_root = qc_root / "logs"
        ssot_cmd = [sys.executable, str(ssot_source_path), "--project-root", str(project_root)]
        if allow_nonstandard_root:
            ssot_cmd.append("--allow-nonstandard-root")
        run_command(ssot_cmd + ["rebuild"], logs_root / "ssot_rebuild.log", env)
        run_command(ssot_cmd + ["validate"], logs_root / "ssot_validate.log", env)

        simulated_dir = preflight_root / "ssot_simulation"
        compared_exports = 0
        for filename, expected_sha in SIMULATED_VIEW_SHA256.items():
            simulated = simulated_dir / filename
            live = project_root / "metadata/ssot/exports" / filename
            ensure_regular(live, "live SSOT export")
            if sha256_file(simulated) != expected_sha or live.read_bytes() != simulated.read_bytes():
                raise Stage15TInstallerError(f"SSOT poststate differs from audited simulation: {filename}")
            compared_exports += 1
        ssot_state = query_ssot_poststate(project_root / "metadata/ssot/rnatr_ssot.sqlite")
        rollback.update("SSOT_REBUILT_AND_VERIFIED", compared_exports=compared_exports, **ssot_state)

        verify_unchanged_scientific_prestate(project_root)
        snapshot = create_snapshot(project_root)
        rollback.update("SNAPSHOT_CREATED", snapshot=str(snapshot))

        manifest_extras = [
            project_root / VERSIONED_README_REL,
            project_root / CURRENT_STRUCTURE_POINTER_REL,
            project_root / "docs/core_freeze/v0.1.1",
            project_root / "docs/contracts/CURRENT_CONTRACTS_v0.1.0.tsv",
            project_root / "docs/contracts/RNA_TR_Scout_Core_Technical_Completion_and_Freeze_contract_v0.1.2.md",
            project_root / "docs/contracts/approved_sources",
            project_root / "docs/contracts/RNA_TR_Scout_Candidate_assignment_reverse_traceability_contract_v0.1.1.md",
            project_root / "docs/contracts/RNA_TR_Scout_Future_extensibility_boundary_contract_v0.1.1.md",
            project_root / "docs/governance/RNA_TR_Scout_Core_Freeze_final_hygiene_audit_v0.1.0.md",
            project_root / "validation/release_gates_v0.3.4.tsv",
            project_root / "validation/golden/v0.1.1",
            project_root / "metadata/ssot/rnatr_ssot.py",
            project_root / "metadata/ssot/rnatr_ssot.sqlite",
            project_root / "metadata/ssot/exports",
            project_root / "metadata/ssot/CURRENT_STATE.md",
            project_root / FREEZE_ROOT_REL,
            qc_root,
        ]
        preliminary_rows, preliminary_sha = write_project_manifest(project_root, manifest_extras)
        rollback.update("PRELIMINARY_MANIFEST_CREATED", rows=preliminary_rows, sha256=preliminary_sha)

        golden = project_root / "validation/golden/v0.1.1/rnatr_golden_regression_v015.py"
        full_qc = project_root / FULL_GOLDEN_QC_REL
        full_work = project_root / FULL_GOLDEN_WORK_REL
        run_command(
            [sys.executable, str(golden), "--full-evidence", "--project-root", str(project_root), "--work-root", str(full_work), "--qc-root", str(full_qc)],
            logs_root / "golden_full_evidence.log",
            env,
        )
        full_summary = {row["metric"]: row["value"] for row in read_tsv(full_qc / "golden_suite_summary.tsv")}
        if full_summary.get("status") != "PASS" or any(full_summary.get(f"tier{i}") != "PASS" for i in range(5)):
            raise Stage15TInstallerError(f"full-evidence golden summary is not complete PASS: {full_summary}")
        rollback.update("FULL_EVIDENCE_GOLDEN_PASS", elapsed_seconds=full_summary.get("elapsed_seconds"))

        # Golden work is deliberately ephemeral. The golden runner may create
        # symlinks inside its isolated project copy; these must not become part
        # of the persistent Freeze poststate inventory. Remove the complete
        # Stage15T golden-work parent after the validated PASS, while retaining
        # the QC summary/logs under qc/.
        golden_work_parent = project_root / FULL_GOLDEN_WORK_REL.parent
        remove_path(golden_work_parent)
        if os.path.lexists(golden_work_parent):
            raise Stage15TInstallerError(f"ephemeral golden work cleanup failed: {golden_work_parent}")
        fsync_dir(golden_work_parent.parent)
        rollback.update("FULL_EVIDENCE_GOLDEN_WORK_CLEANED", ephemeral_work=str(golden_work_parent))

        registration_record = {
            "contract_version": "rnatr_core_freeze_registration_record_v0.1.1",
            "freeze_id": FREEZE_ID,
            "status": FINAL_STATUS,
            "registration_effective_at": SSOT_REGISTRATION_EFFECTIVE_AT,
            "installer_executed_at_utc": utc_now(),
            "owner_review_bundle_sha256": OWNER_REVIEW_BUNDLE_SHA256,
            "owner_response": OWNER_RESPONSE,
            "corrected_preflight_bundle_sha256": bindings["corrected_archive_sha256"],
            "installer_sha256": sha256_file(Path(__file__).resolve()),
            "installer_promotion_audit_sha256": INSTALLER_PROMOTION_AUDIT_SHA256,
            "promoted_hotfix_candidate_sha256": PROMOTED_HOTFIX_CANDIDATE_SHA256,
            "hotfix_read_only_audit_log_sha256": HOTFIX_READ_ONLY_AUDIT_LOG_SHA256,
            "historical_v0_1_0_manifest_sha256": bindings["historical_manifest_sha256"],
            "historical_readme_sha256": EXPECTED_PRESTATE["docs/README_CANONICAL_STRUCTURE.md"],
            "current_readme_path": VERSIONED_README_REL.as_posix(),
            "current_structure_pointer_sha256": CURRENT_STRUCTURE_POINTER_SHA256,
            "release_gates_sha256": sha256_file(project_root / "validation/release_gates_v0.3.4.tsv"),
            "core_freeze_packet_sha256": sha256_file(project_root / "docs/core_freeze/v0.1.1/RNA_TR_Scout_Core_Freeze_Packet_v0.1.1.md"),
            "ctc_contract_sha256": sha256_file(project_root / "docs/contracts/RNA_TR_Scout_Core_Technical_Completion_and_Freeze_contract_v0.1.2.md"),
            "ssot_source_sha256": sha256_file(project_root / "metadata/ssot/rnatr_ssot.py"),
            "ssot_database_sha256": sha256_file(project_root / "metadata/ssot/rnatr_ssot.sqlite"),
            "current_pipeline_sha256": sha256_file(project_root / "metadata/ssot/exports/current_pipeline.tsv"),
            "full_evidence_golden": full_summary,
            "scientific_core_or_schema_modified": False,
            "active_pipeline_modified": False,
            "public_git_release_status": "NOT_YET_BOUND_OPEN",
            "biology_layer_status": "POST_FREEZE_OPEN",
            "downloads_cleanup": False,
            "rollback_retained": True,
            "final_manifest_binding": "core_freeze_manifest.tsv plus SHA-256 sidecar; exact SHA emitted in output bundle and terminal",
            "final_post_manifest_tier0_evidence": "captured outside project and retained in Stage15T output bundle",
        }
        record_path = project_root / FREEZE_ROOT_REL / "registration_record.json"
        atomic_write_bytes(record_path, (json.dumps(registration_record, indent=2, sort_keys=True) + "\n").encode())

        final_rows, final_manifest_sha = write_project_manifest(project_root, manifest_extras)
        rollback.update("FINAL_MANIFEST_CREATED", rows=final_rows, sha256=final_manifest_sha)

        external_summary, external_summary_bytes, external_log_bytes = run_external_final_tier0(project_root, golden, env)
        verify_unchanged_scientific_prestate(project_root)
        verify_project_manifest(project_root, project_root / FREEZE_ROOT_REL / "core_freeze_manifest.tsv")
        manifest_sidecar = project_root / FREEZE_ROOT_REL / "core_freeze_manifest.tsv.sha256"
        sidecar_parts = manifest_sidecar.read_text(encoding="utf-8").strip().split()
        if len(sidecar_parts) < 2 or sidecar_parts[0] != final_manifest_sha or sidecar_parts[-1] != "core_freeze_manifest.tsv":
            raise Stage15TInstallerError("final manifest sidecar mismatch")
        rollback.update("FINAL_POST_MANIFEST_TIER0_PASS", elapsed_seconds=external_summary.get("elapsed_seconds"))

        output_root.mkdir(parents=True)
        output_record = dict(registration_record)
        output_record.update({
            "final_manifest_sha256": final_manifest_sha,
            "final_manifest_rows": final_rows,
            "final_post_manifest_tier0": external_summary,
            "rollback_path": str(rollback.root),
        })
        atomic_write_bytes(output_root / "registration_record.json", (json.dumps(output_record, indent=2, sort_keys=True) + "\n").encode())
        atomic_copy_file(project_root / FREEZE_ROOT_REL / "core_freeze_manifest.tsv", output_root / "core_freeze_manifest.tsv")
        atomic_copy_file(manifest_sidecar, output_root / "core_freeze_manifest.tsv.sha256")
        atomic_copy_file(full_qc / "golden_suite_summary.tsv", output_root / "golden_full_evidence_summary.tsv")
        atomic_copy_file(logs_root / "golden_full_evidence.log", output_root / "golden_full_evidence.run.log")
        atomic_write_bytes(output_root / "golden_final_post_manifest_tier0_summary.tsv", external_summary_bytes)
        atomic_write_bytes(output_root / "golden_final_post_manifest_tier0.run.log", external_log_bytes)
        atomic_write_bytes(output_root / "RNA_TR_Scout_Stage15T_final_installer_hotfix_Pro_promotion_audit_v0.1.5.md", promotion_audit_bytes())
        atomic_copy_file(Path(__file__).resolve(), output_root / Path(__file__).name)
        installer_sidecar = Path(__file__).resolve().with_name(Path(__file__).name + ".sha256")
        parse_sidecar(installer_sidecar, Path(__file__).resolve())
        atomic_copy_file(installer_sidecar, output_root / installer_sidecar.name)
        atomic_write_bytes(output_root / "installed_payload.tsv", tsv_bytes(install_rows, ["source", "destination", "sha256"]))

        qc_rows = [
            {"metric": "status", "value": "PASS_LOCAL_CORE_FREEZE_REGISTERED_WITH_SCOPE"},
            {"metric": "freeze_id", "value": FREEZE_ID},
            {"metric": "scientific_core_or_schema_modified", "value": "false"},
            {"metric": "active_pipeline_modified", "value": "false"},
            {"metric": "historical_v0.1.0_manifest", "value": "PASS_121_OF_121"},
            {"metric": "historical_readme_preserved", "value": "true"},
            {"metric": "owner_approved_scope_preserved", "value": "true"},
            {"metric": "ssot_rebuild", "value": "PASS"},
            {"metric": "full_evidence_golden", "value": "PASS"},
            {"metric": "final_post_manifest_tier0", "value": "PASS"},
            {"metric": "final_manifest_rows", "value": str(final_rows)},
            {"metric": "final_manifest_sha256", "value": final_manifest_sha},
            {"metric": "downloads_cleanup", "value": "false"},
            {"metric": "rollback_retained", "value": "true"},
            {"metric": "human_visual_review_required", "value": "false"},
        ]
        atomic_write_bytes(output_root / "stage15t_final_registration.qc.tsv", tsv_bytes(qc_rows, ["metric", "value"]))
        out_manifest = []
        for path in sorted(item for item in output_root.rglob("*") if item.is_file() and item.name != "artifact_manifest.tsv"):
            out_manifest.append({"path": path.relative_to(output_root).as_posix(), "bytes": str(path.stat().st_size), "sha256": sha256_file(path)})
        atomic_write_bytes(output_root / "artifact_manifest.tsv", tsv_bytes(out_manifest, ["path", "bytes", "sha256"]))

        create_deterministic_tar_gz(output_root, output_bundle, downloads)
        output_sha = sha256_file(output_bundle)
        atomic_write_bytes(output_sidecar, f"{output_sha}  {output_bundle.name}\n".encode())

        rollback.write_poststate_guard()
        rollback.update(
            "INSTALL_COMPLETE",
            status="PASS",
            final_manifest_sha256=final_manifest_sha,
            output_bundle_sha256=output_sha,
        )

        print("===== RNA-TR-SCOUT STAGE15T FINAL CORE FREEZE REGISTRATION =====")
        print(f"stage_version\t{VERSION}")
        print("status\tPASS_LOCAL_CORE_FREEZE_REGISTERED_WITH_SCOPE")
        print(f"freeze_id\t{FREEZE_ID}")
        print("scientific_core_or_schema_modified\tfalse")
        print("active_pipeline_modified\tfalse")
        print("historical_v0.1.0_manifest\tPASS_121_OF_121")
        print("historical_readme_preserved\ttrue")
        print("ssot_rebuild\tPASS")
        print("full_evidence_golden\tPASS")
        print("final_post_manifest_tier0\tPASS")
        print("downloads_cleanup\tfalse")
        print("rollback_retained\ttrue")
        print("human_visual_review_required\tfalse")
        print(f"FINAL_MANIFEST_ROWS\t{final_rows}")
        print(f"FINAL_MANIFEST_SHA256\t{final_manifest_sha}")
        print(f"OUTPUT_BUNDLE\t{output_bundle}")
        print(f"OUTPUT_BUNDLE_SHA256\t{output_sha}")
        print("NEXT_REVIEW\tPRO_POST_INSTALL_FINAL_FREEZE_AUDIT")
        return 0
    except BaseException as exc:
        try:
            if rollback.root.exists():
                rollback.capture_failure(exc)
            if rollback.root.exists() and rollback.mutated:
                rollback.restore()
            cleanup_partial_outputs(output_root, output_bundle, output_sidecar)
            if rollback.root.exists():
                archived = rollback.archive("failed_rollback_pass")
                print(f"STAGE15T_AUTOMATIC_ROLLBACK\tPASS\t{archived}", file=sys.stderr)
        except BaseException as rollback_exc:
            raise Stage15TInstallerError(
                f"installation failed and rollback also failed: install={exc!r}; rollback={rollback_exc!r}"
            ) from exc
        raise
    finally:
        lock.unlink(missing_ok=True)


def explicit_rollback(project_root: Path) -> int:
    manager = RollbackManager(project_root)
    if not manager.root.is_dir():
        raise Stage15TInstallerError(f"rollback root missing: {manager.root}")
    ensure_regular(manager.journal, "rollback journal")
    journal = json.loads(manager.journal.read_text(encoding="utf-8"))
    if journal.get("version") != VERSION or journal.get("freeze_id") != FREEZE_ID:
        raise Stage15TInstallerError(f"rollback journal binding mismatch: {journal}")
    manager.records = read_tsv(manager.root / "prestate_backup_manifest.tsv")
    manager.prestate_inventory = read_tsv(manager.root / "prestate_content_manifest.tsv")
    complete = journal.get("phase") == "INSTALL_COMPLETE" and journal.get("status") == "PASS"
    if complete:
        manager.verify_poststate_guard()
    elif journal.get("phase") == "ROLLBACK_COMPLETE":
        verify_inventory(project_root, manager.prestate_inventory, BACKUP_TARGETS)
    elif not bool(journal.get("mutated")):
        verify_inventory(project_root, manager.prestate_inventory, BACKUP_TARGETS)
    manager.mutated = True
    manager.restore()
    label = "explicit_rollback_pass" if complete else "explicit_recovery_rollback_pass"
    archived = manager.archive(label)
    (project_root / LOCK_REL).unlink(missing_ok=True)
    print("STAGE15T_EXPLICIT_ROLLBACK\tPASS")
    print(f"rollback_mode\t{'POST_INSTALL_GUARDED' if complete else 'INCOMPLETE_INSTALL_RECOVERY'}")
    print(f"rollback_archive\t{archived}")
    return 0


def self_test() -> int:
    source = final_ssot_source_bytes()
    compile(source, "<selftest-final-ssot>", "exec")
    load_embedded_ssot_module()
    if sha256_bytes(CURRENT_STRUCTURE_POINTER_BYTES) != CURRENT_STRUCTURE_POINTER_SHA256:
        raise Stage15TInstallerError("self-test pointer hash failed")
    promotion_audit_bytes()

    with tempfile.TemporaryDirectory(prefix="rnatr_stage15t_installer_selftest_") as td:
        root = Path(td)
        source_file = root / "source.txt"
        destination = root / "d/destination.txt"
        source_file.write_text("abc\n", encoding="utf-8")
        atomic_copy_file(source_file, destination)
        if destination.read_bytes() != source_file.read_bytes():
            raise Stage15TInstallerError("self-test atomic copy failed")

        rows = [{"path": "x", "bytes": "1", "sha256": "0" * 64}]
        roundtrip = root / "roundtrip.tsv"
        atomic_write_bytes(roundtrip, tsv_bytes(rows, ["path", "bytes", "sha256"]))
        if read_tsv(roundtrip) != rows:
            raise Stage15TInstallerError("self-test TSV roundtrip failed")

        project = root / "project"
        for rel, content in [
            ("metadata/ssot/rnatr_ssot.py", "old source\n"),
            ("metadata/ssot/rnatr_ssot.sqlite", "old db\n"),
            ("metadata/ssot/exports/current_pipeline.tsv", "h\tv\n1\t2\n"),
            ("metadata/ssot/CURRENT_STATE.md", "old state\n"),
            ("metadata/ssot/backups/old.txt", "old backup\n"),
        ]:
            path = project / rel
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
        manager = RollbackManager(project)
        manager.initialize()
        original = inventory_targets(project, BACKUP_TARGETS)
        manager.mark_mutated("SELFTEST_MUTATE")
        (project / "metadata/ssot/rnatr_ssot.py").write_text("new\n", encoding="utf-8")
        new_path = project / VERSIONED_README_REL
        new_path.parent.mkdir(parents=True, exist_ok=True)
        new_path.write_text("new\n", encoding="utf-8")
        for rel in NEW_PROJECT_TARGETS:
            remove_path(project / rel)
        for record in manager.records:
            target = project / str(record["path"])
            remove_path(target)
            if record["existed"]:
                source_backup = manager.files_root / str(record["path"])
                if record["kind"] == "directory":
                    copy_tree_exact(source_backup, target)
                else:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(source_backup, target)
        verify_inventory(project, original, BACKUP_TARGETS)

        ephemeral_rel = str(FULL_GOLDEN_WORK_REL.parent)
        if ephemeral_rel not in NEW_PROJECT_TARGETS:
            raise Stage15TInstallerError("self-test ephemeral work missing from rollback cleanup targets")
        if ephemeral_rel in POSTSTATE_GUARD_TARGETS:
            raise Stage15TInstallerError("self-test ephemeral work incorrectly present in persistent poststate guard")
        ephemeral = project / FULL_GOLDEN_WORK_REL.parent
        symlink_parent = ephemeral / "golden_full_evidence/tier2/work/units/shard_000/attempt_001/work/project/config/evidence_schema"
        symlink_parent.mkdir(parents=True, exist_ok=True)
        (symlink_parent / "real_v03").mkdir()
        (symlink_parent / "v0.3").symlink_to("real_v03", target_is_directory=True)
        remove_path(ephemeral)
        if os.path.lexists(ephemeral):
            raise Stage15TInstallerError("self-test ephemeral symlink tree cleanup failed")

        bundle_root = root / "bundle"
        bundle_root.mkdir()
        (bundle_root / "a.txt").write_text("a\n", encoding="utf-8")
        first = root / "first.tar.gz"
        second = root / "second.tar.gz"
        create_deterministic_tar_gz(bundle_root, first, root)
        create_deterministic_tar_gz(bundle_root, second, root)
        if sha256_file(first) != sha256_file(second):
            raise Stage15TInstallerError("self-test deterministic tar failed")

    print("SELF_TEST_PASS")
    print(f"version\t{VERSION}")
    print(f"embedded_final_ssot_sha256\t{FINAL_SSOT_SOURCE_SHA256}")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description="Guarded Stage15T final local Core Freeze registration installer")
    parser.add_argument("--self-test", action="store_true")
    parser.add_argument("--project-root", type=Path, default=DEFAULT_PROJECT_ROOT)
    parser.add_argument("--downloads", type=Path, default=DEFAULT_DOWNLOADS)
    parser.add_argument("--corrected-preflight-root", type=Path)
    parser.add_argument("--execute", action="store_true")
    parser.add_argument("--confirm-freeze-id")
    parser.add_argument("--rollback", action="store_true")
    parser.add_argument("--allow-nonstandard-root", action="store_true", help=argparse.SUPPRESS)
    args = parser.parse_args()
    try:
        if args.self_test:
            return self_test()
        installer_sha256 = verify_self_sidecar()
        project_root = args.project_root.resolve()
        downloads = args.downloads.resolve()
        if not project_root.is_dir() or project_root.is_symlink():
            raise Stage15TInstallerError(f"project root missing/invalid: {project_root}")
        if not downloads.is_dir() or downloads.is_symlink():
            raise Stage15TInstallerError(f"Downloads missing/invalid: {downloads}")
        preflight_root = (args.corrected_preflight_root or downloads / CORRECTED_PREFLIGHT_NAME).resolve()
        if args.rollback:
            if args.confirm_freeze_id != FREEZE_ID:
                raise Stage15TInstallerError("explicit rollback requires exact --confirm-freeze-id")
            return explicit_rollback(project_root)
        if not args.execute:
            bindings = verify_corrected_preflight(preflight_root, downloads, project_root)
            print("===== RNA-TR-SCOUT STAGE15T FINAL INSTALLER READ-ONLY AUDIT =====")
            print(f"stage_version\t{VERSION}")
            print("status\tPASS_READY_FOR_PRO_EXECUTION_AUTHORIZATION")
            print(f"installer_sha256\t{installer_sha256}")
            print(f"promoted_hotfix_candidate_sha256\t{PROMOTED_HOTFIX_CANDIDATE_SHA256}")
            print(f"hotfix_read_only_audit_log_sha256\t{HOTFIX_READ_ONLY_AUDIT_LOG_SHA256}")
            print(f"project_root\t{project_root}")
            print(f"corrected_preflight_root\t{preflight_root}")
            print(f"corrected_preflight_bundle_sha256\t{bindings['corrected_archive_sha256']}")
            print(f"corrected_preflight_manifest_rows\t{bindings['manifest_count']}")
            print(f"project_prestate_guards\t{bindings['project_guard_count']}")
            print(f"historical_v0.1.0_manifest_rows\t{bindings['historical_manifest_rows']}")
            print(f"historical_v0.1.0_manifest_sha256\t{bindings['historical_manifest_sha256']}")
            print("historical_readme_preserved_plan\ttrue")
            print(f"final_ssot_source_sha256\t{FINAL_SSOT_SOURCE_SHA256}")
            print(f"ssot_runtime_overlay_compared_tables\t{bindings['ssot_overlay']['compared_tables']}")
            print(f"ssot_runtime_overlay_compared_views\t{bindings['ssot_overlay']['compared_views']}")
            print("ssot_runtime_overlay_audit\tPASS")
            print(f"ssot_full_rebuild_validation_checks\t{bindings['ssot_full_rebuild']['validation_checks']}")
            print(f"ssot_full_rebuild_compared_views\t{bindings['ssot_full_rebuild']['compared_views']}")
            print(f"ssot_full_rebuild_scan_warnings\t{bindings['ssot_full_rebuild']['scan_warnings']}")
            print("ssot_full_rebuild_read_only_audit\tPASS")
            print("owner_approved_payload_preserved\ttrue")
            print("scientific_core_or_schema_modified\tfalse")
            print("active_pipeline_modified\tfalse")
            print("project_mutation\tfalse")
            print("downloads_cleanup\tfalse")
            print("human_visual_review_required\tfalse")
            print("NEXT_ACTION\tUPLOAD_THIS_AUDIT_LOG_FOR_PRO_APPROVAL_BEFORE_EXECUTE")
            return 0
        if args.confirm_freeze_id != FREEZE_ID:
            raise Stage15TInstallerError(f"execution requires --confirm-freeze-id {FREEZE_ID}")
        return execute_install(project_root, downloads, preflight_root, args.allow_nonstandard_root)
    except (Stage15TInstallerError, OSError, ValueError, sqlite3.Error, subprocess.SubprocessError, tarfile.TarError, zlib.error) as exc:
        print(f"STAGE15T_INSTALLER_ERROR\t{type(exc).__name__}\t{exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
